.fit-svg .fit-sum text { font-size: 17px; }
.fit-svg .fit-sum g text { font-size: 11.5px; }
.fit-svg .fit-g, .fit-svg .fit-g text { fill: var(--gold); }
.fit-svg .fit-u, .fit-svg .fit-u text { fill: var(--fit-u); }
.fit-svg .fit-o { fill-opacity: .55; }
.fit-g { color: var(--gold); }
.fit-u { color: var(--fit-u); }
.fit-pp { transform-box: fill-box; transform-origin: center; }
.fit-s ~ .fit-s, .fit-ot { opacity: 0; }
.fit-s { animation: 36s linear infinite; animation-name: var(--kf); }
.fit-dr, .fit-fd, .fit-ot, .fit-pp { animation: 36s cubic-bezier(.3, .7, .4, 1) infinite; animation-delay: var(--d); }
.fit-dr { animation-name: fit-dr; }
.fit-fd { animation-name: fit-fd; }
.fit-ot { animation-name: fit-ot; }
.fit-pp { animation-name: fit-pp; }
@keyframes fit-s1 { 0%, 26.39% { opacity: 1; } 27.78%, 98.61% { opacity: 0; } 100% { opacity: 1; } }
@keyframes fit-s2 { 0%, 26.39% { opacity: 0; } 27.78%, 48.61% { opacity: 1; } 50%, 100% { opacity: 0; } }
@keyframes fit-s3 { 0%, 48.61% { opacity: 0; } 50%, 76.39% { opacity: 1; } 77.78%, 100% { opacity: 0; } }
@keyframes fit-s4 { 0%, 76.39% { opacity: 0; } 77.78%, 98.61% { opacity: 1; } 100%, 100% { opacity: 0; } }
@keyframes fit-dr { 0%, 70.83% { opacity: 0; transform: translateY(-12px); } 71.67% { opacity: 1; } 72.5%, 100% { opacity: 1; transform: none; } }
@keyframes fit-fd { 0%, 70.83% { opacity: 0; } 72.08%, 100% { opacity: 1; } }
@keyframes fit-ot { 0%, 70.83% { opacity: 1; } 72.22%, 100% { opacity: 0; } }
@keyframes fit-pp { 0%, 70.83% { opacity: 0; transform: scale(.3); } 71.53% { opacity: 1; transform: scale(1.25); } 72.08%, 100% { opacity: 1; transform: none; } }
@media (prefers-reduced-motion: reduce) {
  .an-fit .fit-s, .an-fit .fit-dr, .an-fit .fit-fd, .an-fit .fit-ot, .an-fit .fit-pp { animation: none; }
}
